import React, { PropsWithChildren, ReactNode } from "react";
import { styled, keyframes, CSS } from "../../../stitches.config";
import * as DialogPrimitive from "@radix-ui/react-dialog";
import { DialogClose, DialogOverlay, DialogTrigger } from "../Dialog/Dialog";
import { Box } from "../../atoms/Box/Box";
import { CloseIcon as DialogCloseIcon } from "../../icons/ui/CloseIcon";
import { DialogBackIcon } from "../../icons/ui/DialogBackIcon";

const contentShow = keyframes({
  "0%": { opacity: 0, transform: "translate(-50%, -48%) scale(.96)" },
  "100%": { opacity: 1, transform: "translate(-50%, -50%) scale(1)" },
});

const contentShowSmall = keyframes({
  "0%": { opacity: 0, transform: "translateY(100vh) scale(1, 1)" },
  "100%": { opacity: 1, transform: "translateY(0) scale(1, 1)" },
});

const StyledContent = styled(DialogPrimitive.Content, {
  "@sm": {
    width: "100%",
    maxWidth: "100%",
    height: "100%",
    top: 0,
    left: 0,
    transition: "transform 500ms ease",
    "@media (prefers-reduced-motion: no-preference)": {
      animation: `${contentShowSmall} 1500ms cubic-bezier(0.16, 1, 0.3, 1) forwards`,
    },
  },
  "@bp2": {
    width: "90vw",
    maxWidth: "559px",
    height: "660px",
    // Short screens (a 1366x768 laptop): stay inside the viewport and let the
    // body scroll, so the bottom actions are always reachable.
    maxHeight: "calc(100dvh - 32px)",
    top: "50%",
    left: "50%",
    transform: "translate(-50%, -50%)",
    "@media (prefers-reduced-motion: no-preference)": {
      animation: `${contentShow} 150ms cubic-bezier(0.16, 1, 0.3, 1) forwards`,
    },
  },
  borderRadius: 16,
  border: "1px solid $bg05",
  backgroundColor: "$bg02",
  boxShadow:
    "hsl(206 22% 7% / 35%) 0px 10px 38px -10px, hsl(206 22% 7% / 20%) 0px 10px 20px -15px",
  position: "fixed",
  "&:focus": { outline: "none" },

  variants: {
    size: {
      stepped: {
        "@bp2": {
          width: "474px",
          height: "740px",
        },
      },
      fitContent: {
        "@bp2": {
          height: "auto",
          maxHeight: "80vh",
        },
      },
    },
  },
});

export type ResponsiveDialogSize = "stepped" | "fitContent";

interface ContentProps {
  css?: CSS;
  children: ReactNode;
  size?: ResponsiveDialogSize;
}

const Content: React.FC<ContentProps> = ({ children, css, size }) => {
  return (
    <DialogPrimitive.Portal>
      <DialogOverlay className="dialog-overlay" />
      <StyledContent className="dialog-styled-content" css={css} size={size}>
        {children}
      </StyledContent>
    </DialogPrimitive.Portal>
  );
};

const Dialog = styled(DialogPrimitive.Root, {});

interface ResponsiveDialogComponentProps {
  open?: boolean;
  setOpen?: (open: boolean) => void;
  children: ReactNode;
}

export const ResponsiveDialogComponent: React.FC<
  ResponsiveDialogComponentProps
> = ({ open, setOpen, children }) => {
  return (
    <Dialog open={open} onOpenChange={setOpen}>
      {children}
    </Dialog>
  );
};
export const ResponsiveDialogStyledContent = StyledContent;

export const ResponsiveDialogIconButton = styled("button", {
  all: "unset",
  fontFamily: "inherit",
  borderRadius: "100%",
  height: 24,
  width: 24,
  display: "inline-flex",
  alignItems: "center",
  justifyContent: "center",
  color: "$textLight",
  position: "absolute",
  top: 10,
  "@sm": {
    left: 10,
  },
  "@bp2": {
    right: 10,
  },
  cursor: "pointer",
  "&:focus": { boxShadow: "0 0 0 2px $textLight" },
});

export const ResponsiveDialogTrigger: React.FC<PropsWithChildren> = ({
  children,
}) => {
  return <DialogTrigger asChild>{children}</DialogTrigger>;
};

export interface ResponsiveDialogProps {
  open?: boolean;
  setOpen?: (open: boolean) => void;
  triggerElement?: React.ReactNode;
  css?: CSS;
  children: ReactNode;
  size?: ResponsiveDialogSize;
}

export const ResponsiveDialog: React.FC<ResponsiveDialogProps> = ({
  open,
  setOpen,
  triggerElement,
  css,
  children,
  size,
}) => (
  <ResponsiveDialogComponent open={open} setOpen={setOpen}>
    <DialogTrigger asChild>{triggerElement}</DialogTrigger>
    <Content css={css} size={size}>
      <Box
        css={
          size === "fitContent"
            ? {
                pt: "$xl",
                pb: "$sm",
                height: "auto",
                maxHeight: "calc(80vh - 16px)",
                display: "flex",
                flexDirection: "column",
                overflow: "hidden",
              }
            : {
                pt: "$xl",
                pb: "$sm",
                height: "100%",
                boxSizing: "border-box",
                overflowY: "auto",
              }
        }
      >
        {children}
      </Box>
      <DialogClose
        asChild
        onClick={setOpen ? () => setOpen(false) : () => null}
      >
        <ResponsiveDialogIconButton
          css={{
            "@bp2": { display: "none" },
          }}
          aria-label="Close"
        >
          <DialogBackIcon />
        </ResponsiveDialogIconButton>
      </DialogClose>
      <DialogClose
        asChild
        onClick={setOpen ? () => setOpen(false) : () => null}
      >
        <ResponsiveDialogIconButton
          css={{
            "@sm": { display: "none" },
          }}
          aria-label="Close"
        >
          <DialogCloseIcon />
        </ResponsiveDialogIconButton>
      </DialogClose>
    </Content>
  </ResponsiveDialogComponent>
);
