import type { ReactNode } from "react";
import { Box, Text } from "../../atoms";
import { styled, type CSS } from "../../../stitches.config";

/**
 * Equal-width metric rows. Breakpoints: @sm ≤900px, @md ≤1200px.
 * - 4 cols: 4 → 2×2 → 1
 * - 3 cols: 3 → 1
 * - 2 cols: 2 → 1
 */
export const MetricWidgetsGrid = styled(Box, {
  display: "grid",
  width: "100%",
  minWidth: 0,
  gap: "$lg",
  alignItems: "stretch",
  variants: {
    columns: {
      2: {
        gridTemplateColumns: "repeat(2, minmax(0, 1fr))",
        "@sm": { gridTemplateColumns: "1fr" },
      },
      3: {
        gridTemplateColumns: "repeat(3, minmax(0, 1fr))",
        "@md": { gridTemplateColumns: "1fr" },
      },
      4: {
        gridTemplateColumns: "repeat(4, minmax(0, 1fr))",
        "@md": { gridTemplateColumns: "repeat(2, minmax(0, 1fr))" },
        "@sm": { gridTemplateColumns: "1fr" },
      },
    },
  },
  defaultVariants: { columns: 3 },
});

export type MetricGridColumns = 2 | 3 | 4;

/** Pass as `css` on `MetricWidget` inside a `MetricWidgetsGrid` cell. */
export const metricWidgetCellCss: CSS = {
  flex: "none",
  width: "100%",
  maxWidth: "100%",
  minWidth: 0,
  height: "100%",
  minHeight: "68px",
  boxSizing: "border-box",
  justifyContent: "space-between",
  "& > div:last-child": {
    marginTop: "auto",
    width: "100%",
    minHeight: "32px",
    alignItems: "flex-end",
  },
};

export function MetricValueText({ children }: { children: ReactNode }) {
  return (
    <Box
      css={{
        display: "flex",
        alignItems: "center",
        width: "100%",
        minHeight: "32px",
      }}
    >
      <Text
        variant="h4"
        css={{
          fontVariantNumeric: "tabular-nums",
          lineHeight: "32px",
          fontWeight: "$semibold",
          textTransform: "none",
        }}
      >
        {children}
      </Text>
    </Box>
  );
}
