import React from "react";
import { Box } from "../../atoms/Box/Box";
import { Flex } from "../../atoms/Flex/Flex";
import { Text } from "../../atoms/Text/Text";
import { TooltipComponent } from "../../atoms/Tooltip/Tooltip";
import { getClientBrandIcon } from "../../icons/clients";
import {
  CLIENT_SLOT_LABEL,
  formatClientLastUpdated,
  parseClientFamily,
  resolveDvClientFamily,
  type PeerClientDetails,
  type PeerClientSlot,
} from "./peerClients";

const ICON_SIZE = 18;

/** Some logos have more internal padding / wider aspect; scale so they match peers. */
const LOGO_DISPLAY_SCALE: Record<string, number> = {
  nethermind: 1.35,
  // Pluto uses the Nethermind mark for now.
  pluto: 1.35,
};

/** Extra CSS filters for logos that are too dark on dark UI. */
const LOGO_FILTER: Record<string, string> = {};

type ClientSlotData = {
  slot: PeerClientSlot;
  raw: string | null;
  lastUpdated: string | null;
};

const slotsFromDetails = (
  details: PeerClientDetails | undefined,
): ClientSlotData[] => [
  {
    slot: "el",
    raw: details?.execution_client ?? null,
    lastUpdated: details?.execution_client_last_updated_at ?? null,
  },
  {
    slot: "cl",
    raw: details?.beacon_client ?? null,
    lastUpdated: details?.beacon_client_last_updated_at ?? null,
  },
  {
    slot: "dv",
    raw: details?.charon_version ?? null,
    lastUpdated: details?.charon_version_last_updated_at ?? null,
  },
  {
    slot: "vc",
    raw: details?.validator_client ?? null,
    lastUpdated: details?.validator_client_last_updated_at ?? null,
  },
];

const ClientSlotIcon: React.FC<{ data: ClientSlotData }> = ({ data }) => {
  const label = CLIENT_SLOT_LABEL[data.slot];
  const raw = data.raw?.trim() || null;

  if (!raw) {
    return (
      <Box
        css={{
          width: ICON_SIZE,
          height: ICON_SIZE,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          flexShrink: 0,
        }}
        aria-label={`${label}: unknown`}
      >
        <Text size="3" color="body" css={{ lineHeight: 1 }}>
          –
        </Text>
      </Box>
    );
  }

  const family =
    data.slot === "dv" ? resolveDvClientFamily(raw) : parseClientFamily(raw);
  const BrandIcon = getClientBrandIcon(family);
  const updated = formatClientLastUpdated(data.lastUpdated);
  const logoScale =
    family && LOGO_DISPLAY_SCALE[family.toLowerCase()]
      ? LOGO_DISPLAY_SCALE[family.toLowerCase()]
      : 1;
  const logoPx = Math.round(ICON_SIZE * logoScale);
  const logoFilter =
    family && LOGO_FILTER[family.toLowerCase()]
      ? LOGO_FILTER[family.toLowerCase()]
      : undefined;

  const tooltip = (
    <Flex direction="column" css={{ gap: "$xxxs" }}>
      <Text size="3" css={{ color: "$bg05", lineHeight: "$base" }}>
        {label}: {raw}
      </Text>
      {updated && (
        <Text size="2" css={{ color: "$bg05", lineHeight: "$base" }}>
          Last updated: {updated}
        </Text>
      )}
    </Flex>
  );

  const trigger = BrandIcon ? (
    <Box
      css={{
        width: ICON_SIZE,
        height: ICON_SIZE,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        flexShrink: 0,
        position: "relative",
        overflow: "visible",
      }}
    >
      <BrandIcon
        size={logoPx}
        alt={`${label}: ${family ?? raw}`}
        css={logoFilter ? { filter: logoFilter } : undefined}
      />
    </Box>
  ) : (
    <Box
      css={{
        width: ICON_SIZE,
        height: ICON_SIZE,
        borderRadius: "50%",
        backgroundColor: "$bg04",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        flexShrink: 0,
      }}
      aria-label={`${label}: ${raw}`}
    >
      <Text size="1" color="body" css={{ lineHeight: 1, fontWeight: "$bold" }}>
        ?
      </Text>
    </Box>
  );

  return (
    <TooltipComponent side="top" content={tooltip}>
      <Box css={{ display: "flex", cursor: "default" }}>{trigger}</Box>
    </TooltipComponent>
  );
};

export type PeerClientIconsProps = {
  /** Structured client fields from peer-info (or equivalent). */
  clientDetails?: PeerClientDetails;
};

/** EL · CL · DV client · VC icons (or – / ?) for one peer's client details. */
export const PeerClientIcons: React.FC<PeerClientIconsProps> = ({
  clientDetails,
}) => (
  <Flex css={{ alignItems: "center", gap: "$xs", minWidth: 0 }}>
    {slotsFromDetails(clientDetails).map((slot) => (
      <ClientSlotIcon key={slot.slot} data={slot} />
    ))}
  </Flex>
);

PeerClientIcons.displayName = "PeerClientIcons";
